def control(obs):
    global distance, phase
    if phase == 0:
        distance += max(0, obs['motion']['v_mps']) * obs['dt']
        if distance < 1.0:
            return (0, 0.55, -23)
        phase = 1
    if obs['hitch_deg'] < -8:
        return (-34, -0.4, -23)
    wake('Trailer following; check bay approach')
    return (2.5*obs['hitch_deg'], 0, -23)

